ALTER TABLE "PointAdjustment" ADD COLUMN IF NOT EXISTS "requestKey" TEXT, ADD COLUMN IF NOT EXISTS "actorId" INTEGER;
CREATE UNIQUE INDEX IF NOT EXISTS "PointAdjustment_requestKey_key" ON "PointAdjustment"("requestKey");
CREATE TABLE IF NOT EXISTS "AuditLog" (id SERIAL PRIMARY KEY,"actorId" INTEGER NOT NULL,action TEXT NOT NULL,"targetType" TEXT NOT NULL,"targetId" INTEGER NOT NULL,before JSONB,after JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "AuditLog_createdAt_idx" ON "AuditLog"("createdAt");
CREATE TABLE IF NOT EXISTS "League" (id SERIAL PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'PRIVATE',"ownerId" INTEGER NOT NULL REFERENCES "User"(id),"tournamentId" INTEGER NOT NULL REFERENCES "Tournament"(id),"startsAt" TIMESTAMP(3) NOT NULL,code TEXT NOT NULL UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT league_kind CHECK(kind IN ('PRIVATE','CLUB')));
CREATE INDEX IF NOT EXISTS "League_tournamentId_idx" ON "League"("tournamentId");
CREATE TABLE IF NOT EXISTS "LeagueMember" (id SERIAL PRIMARY KEY,"leagueId" INTEGER NOT NULL REFERENCES "League"(id),"userId" INTEGER NOT NULL REFERENCES "User"(id),"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("leagueId","userId"));
CREATE INDEX IF NOT EXISTS "LeagueMember_userId_idx" ON "LeagueMember"("userId");
CREATE TABLE IF NOT EXISTS "Challenge" (id SERIAL PRIMARY KEY,name TEXT NOT NULL,"matchId" INTEGER NOT NULL UNIQUE REFERENCES "Match"(id),"closesAt" TIMESTAMP(3) NOT NULL,bonus INTEGER NOT NULL DEFAULT 3,"createdBy" INTEGER NOT NULL REFERENCES "User"(id),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT challenge_bonus CHECK(bonus=3));
CREATE TABLE IF NOT EXISTS "ChallengePick" (id SERIAL PRIMARY KEY,"challengeId" INTEGER NOT NULL REFERENCES "Challenge"(id),"userId" INTEGER NOT NULL REFERENCES "User"(id),winner INTEGER NOT NULL CHECK(winner IN (1,2)),"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("challengeId","userId"));
